// ==========================================
// HC-SR04 Ultrasonic: เซ็นเซอร์วัดระยะทาง
// เปลี่ยนหมายเลขขา TRIG_PIN และ ECHO_PIN ด้านล่างได้ทันที
// ==========================================
#define TRIG_PIN 9    // ขาส่งคำสั่งยิงคลื่นเสียง (Digital Output)
#define ECHO_PIN 10   // ขารับสัญญาณคลื่นสะท้อน (Digital Input)

void setup() {
  Serial.begin(9600);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  Serial.println("HC-SR04 Ultrasonic Sensor Ready!");
}

void loop() {
  // เคลียร์สัญญาณขา Trig ให้เป็น LOW ชั่วครู่
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);

  // ส่งสัญญาณพัลส์ HIGH นาน 10 ไมโครวินาที เพื่อสั่งยิงคลื่นเสียง
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  // จับเวลาที่ขา Echo เป็น HIGH (หน่วยเป็นไมโครวินาที) Timeout ที่ 30,000µs (~5 เมตร)
  long duration = pulseIn(ECHO_PIN, HIGH, 30000);

  if (duration == 0) {
    Serial.println("อยู่นอกระยะตรวจจับ (เกิน 400 cm หรือไม่มีวัตถุ)");
  } else {
    // ความเร็วเสียงในอากาศประมาณ 0.0343 ซม./ไมโครวินาที (หาร 2 เพราะไป-กลับ)
    float distanceCm = (duration * 0.0343) / 2.0;

    Serial.print("ระยะทาง: ");
    Serial.print(distanceCm, 1);
    Serial.println(" cm");
  }

  delay(150); // รอ 150ms ก่อนวัดรอบถัดไป
}
